import { Video } from '@refy-design/web';
import type { ComponentProps } from 'react';
const media = {
  gradient: 'https://refy.design/demo/degrade.webm',
  gradientPoster: 'https://refy.design/demo/degrade-capa.jpg',
};
export function Example() {
  const args: Pick<
    ComponentProps<typeof Video>,
    'src' | 'poster' | 'title' | 'description'
  > = {
    src: media.gradient,
    poster: media.gradientPoster,
    title: 'Theme colors in motion',
    description: 'Six seconds, no sound.',
  };
  return <Video {...args} />;
}

